def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_d = 0
    my_d = 0
    unprov = 0
    for i in range(n):
        m = history[i][0]
        o = history[i][1]
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprov += 1

    pun = 0
    tol = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                pun += 1
            else:
                tol += 1

    w5 = 5 if n >= 5 else n
    recent_d = 0
    for i in range(n - w5, n):
        if history[i][1] == 'D':
            recent_d += 1

    w6 = 6 if n >= 6 else n
    recent_my_d = 0
    recent_unprov = 0
    for i in range(n - w6, n):
        m = history[i][0]
        o = history[i][1]
        if m == 'D':
            recent_my_d += 1
        if o == 'D' and (i == 0 or history[i - 1][0] == 'C'):
            recent_unprov += 1

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    hostile = False
    if n >= 2:
        if unprov >= max(2, n * 0.25) and recent_d >= 2 and tol == 0:
            hostile = True
        if streak >= 5 and tol == 0:
            hostile = True
    if n >= 6:
        if opp_d >= n * 0.7 and unprov >= max(3, n * 0.2):
            hostile = True
        if recent_d >= 4 and unprov >= 2 and tol == 0:
            hostile = True
        if unprov >= max(4, n * 0.3):
            hostile = True

    if hostile:
        return 'D'

    if n == 50 and opp_d == 0 and my_d == 0:
        return 'D'

    if n == 51 and last_m == 'D' and last_o == 'C' and opp_d == 0 and my_d > 0:
        return 'C'

    if opp_d == 0 and my_d > 0 and last_o == 'C':
        return 'D'

    if last_o == 'C':
        if (n >= 90 and my_d > 0 and opp_d <= max(2, n * 0.10) and
                unprov <= max(1, n * 0.05) and recent_d == 0 and tol > pun):
            return 'D'
        return 'C'

    if last_m == 'D':
        if (opp_d <= max(3, n * 0.30) and unprov <= max(3, n * 0.20) and
                streak <= 3 and recent_my_d <= 4):
            return 'C'
        return 'D'

    if n >= 2 and history[-2][0] == 'D':
        if streak <= 4:
            return 'C'
        return 'D'

    if (recent_my_d > 0 and recent_unprov <= 1 and
            opp_d <= max(5, n * 0.25) and unprov <= max(4, n * 0.15) and
            streak <= 4):
        return 'C'

    return 'D'
